pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),stage=document.getElementById("stage"),nav=document.getElementById("nav"),cardFront=document.getElementById("card-front"),cardBack=document.getElementById("card-back"),indicator=document.getElementById("card-indicator");let cards=[],currentIndex=0;async function processFile(e){if(e){dropZone.style.display="none",loading.style.display="block";try{const n=await e.arrayBuffer(),t=await pdfjsLib.getDocument(n).promise;let r="";for(let e=1;e<=t.numPages;e++){const n=await t.getPage(e);r+=(await n.getTextContent()).items.map(e=>e.str).join(" ")+" "}extractCards(r)}catch(e){alert("Error processing PDF."),location.reload()}}}function extractCards(e){loading.style.display="none",stage.style.display="block",nav.style.display="flex";(e.match(/[^.!?]+[.!?]+/g)||[]).forEach(e=>{if(e.includes(" means ")||e.includes(" is defined as ")||e.includes(":")){let n=e.split(/ means | is defined as |:/i);n.length>=2&&n[0].trim().split(" ").length<5&&cards.push({front:n[0].trim(),back:n[1].trim()})}}),0===cards.length&&cards.push({front:"Sample Concept",back:"This is a placeholder since no definitions were found."}),renderCard(),setTimeout(()=>{const e=cards.map((e,n)=>`Card ${n+1}\nFront: ${e.front}\nBack: ${e.back}`).join("\n\n"),n=new Blob([e],{type:"text/plain"}),t=URL.createObjectURL(n),r=document.createElement("a");r.href=t,r.download="pdfindi_flashcards.txt",r.click()},2e3)}function renderCard(){document.getElementById("card").classList.remove("is-flipped"),cardFront.innerText=cards[currentIndex].front,cardBack.innerText=cards[currentIndex].back,indicator.innerText=`${currentIndex+1} of ${cards.length}`}function nextCard(){currentIndex=(currentIndex+1)%cards.length,renderCard()}function prevCard(){currentIndex=(currentIndex-1+cards.length)%cards.length,renderCard()}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=e=>processFile(e.target.files[0]);